	/**
	 * Creates UI views for Epidemic.
	 */
	public void createGraphicViews() {
		super.createGraphicViews();
		{
			org.ascape.view.vis.Overhead2DView cityView = new org.ascape.view.vis.Overhead2DView();
			cityView.setAgentSize(10);
			city.addView(cityView);
			org.ascape.util.vis.DrawFeature locationStyle2D = new com.metascape.epi.LocationStyle2D();
			locationStyle2D.setName("Location Style 2D");
			city.addDrawFeature(locationStyle2D);
			org.ascape.util.vis.DrawFeature individualStyle2D = new com.metascape.epi.IndividualStyle2D();
			individualStyle2D.setName("Individual Style 2D");
			city.addDrawFeature(individualStyle2D);
			cityView.getDrawSelection().setSelected(individualStyle2D, true);
			cityView.getDrawSelection().setSelected(locationStyle2D, true);
			cityView.getDrawSelection().setSelected(
					cityView.agents_oval_cells_draw_feature, false);
			cityView.getDrawSelection().setSelected(
					cityView.cells_fill_draw_feature, true);
			cityView.getDrawSelection().moveToFront(
					cityView.cells_fill_draw_feature);
		}
		{
			org.ascape.view.vis.ChartView chart = new org.ascape.view.vis.ChartView();
			addView(chart);
			//if (getRunner().getEnvironment() instanceof org.ascape.runtime.applet.AppletEnvironment) {
			//    chart.getChart().getLegend().setAnchor(com.jrefinery.chart.Legend.SOUTH);
			//}
			java.awt.Graphics dummyGraphics = new java.awt.image.BufferedImage(
					10, 10, java.awt.image.BufferedImage.TYPE_INT_RGB)
					.getGraphics();

			org.ascape.model.Scape individualScape = new Epidemic();
			individualScape
					.setRunner(new org.ascape.runtime.NonGraphicRunner());
			Individual individual = new Individual() {
				public void requestUpdate() {
				}
			};
			individualScape.add(individual);

			org.ascape.model.HostCell individualHost = new org.ascape.model.HostCell() {
				public void requestUpdate() {
				}
			};
			individualHost
					.setOccupant((org.ascape.model.CellOccupant) individual);

			IndividualStyle2D individualStyle2D = new IndividualStyle2D();

			individual.setStatus(StatusEnum.susceptible);

			individualStyle2D.draw(dummyGraphics, individualHost, 4, 4);

			{
				java.awt.Color agentColor = dummyGraphics.getColor();
				chart.addSeries("Count Individual Susceptible Status",
						agentColor);
			}

			individual.setStatus(StatusEnum.exposed);

			individualStyle2D.draw(dummyGraphics, individualHost, 4, 4);

			{
				java.awt.Color agentColor = dummyGraphics.getColor();
				chart.addSeries("Count Individual Exposed Status", agentColor);
			}

			individual.setStatus(StatusEnum.asymptomInfectious);

			individualStyle2D.draw(dummyGraphics, individualHost, 4, 4);

			{
				java.awt.Color agentColor = dummyGraphics.getColor();
				chart.addSeries("Count Individual Asymptom Infectious Status",
						agentColor);
			}

			individual.setStatus(StatusEnum.symptomInfectious);

			individualStyle2D.draw(dummyGraphics, individualHost, 4, 4);

			{
				java.awt.Color agentColor = dummyGraphics.getColor();
				chart.addSeries("Count Individual Symptom Infectious Status",
						agentColor);
			}

			individual.setStatus(StatusEnum.recovered);

			individualStyle2D.draw(dummyGraphics, individualHost, 4, 4);

			{
				java.awt.Color agentColor = dummyGraphics.getColor();
				chart
						.addSeries("Count Individual Recovered Status",
								agentColor);
			}

			individual.setStatus(StatusEnum.dead);

			individualStyle2D.draw(dummyGraphics, individualHost, 4, 4);

			{
				java.awt.Color agentColor = dummyGraphics.getColor();
				chart.addSeries("Count Individual Dead Status", agentColor);
			}

			org.ascape.model.Scape locationScape = new Epidemic();
			locationScape.setRunner(new org.ascape.runtime.NonGraphicRunner());
			Location location = new Location() {
				public void requestUpdate() {
				}
			};
			locationScape.add(location);

			LocationStyle2D locationStyle2D = new LocationStyle2D();
		}
	}

